# Generated by Claude Code

import importlib.util
import json
from pathlib import Path

_mod_path = Path(__file__).resolve().parent.parent / "nice-check.py"
_spec = importlib.util.spec_from_file_location("nice_check", _mod_path)
nice_check = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(nice_check)


def write(root: Path, rel: str, text: str) -> str:
    path = root / rel
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")
    return rel


def make_repo(root: Path, tracked=(), eol=None) -> nice_check.Repo:
    return nice_check.Repo(root, tuple(tracked), eol or {})


def make_skill(root: Path, plugin: str | None, name: str, frontmatter: str, body: str = "\n# Body\n") -> str:
    parent = f"plugins/{plugin}/skills" if plugin else ".claude/skills"
    return write(root, f"{parent}/{name}/SKILL.md", f"---\n{frontmatter}---\n{body}")


def make_rule(root: Path, plugin: str, name: str, frontmatter: str, body: str = "\n# Body\n") -> str:
    return write(root, f"plugins/{plugin}/rules/{name}.md", f"---\n{frontmatter}---\n{body}")


def managed(version: str = "1.0.0") -> str:
    return f'managed-by: https://example.invalid\nversion: "{version}"\nlast-change: "2026-01-01 12:00:00"\n'


def authored(name: str) -> str:
    return (
        f"name: {name}\n"
        "description: >-\n  Use when testing.\n"
        "disable-model-invocation: true\n"
        "user-invocable: true\n"
        "managed-by: https://example.invalid\n"
        'version: "1.0.0"\n'
        'last-change: "2026-01-01 12:00:00"\n'
    )


def repo_local(name: str) -> str:
    return (
        f"name: {name}\n"
        "description: >-\n  Use when testing.\n"
        "disable-model-invocation: true\n"
        "user-invocable: true\n"
        'last-change: "2026-01-01 12:00:00"\n'
    )


def messages(findings) -> list[str]:
    return [f"{finding.path}:{finding.line}: {finding.message}" for finding in findings]


def write_marketplace(root: Path, plugins: list[dict]) -> None:
    write(root, ".claude-plugin/marketplace.json", json.dumps({"name": "test", "plugins": plugins}))


# -- frontmatter parsing -----------------------------------------------------


class TestParseFrontmatter:
    def test_reads_plain_scalar_and_block_scalar(self):
        parsed = nice_check.parse_frontmatter("---\nname: demo\ndescription: >-\n  Line one\n  line two.\n---\nbody\n")

        assert parsed["name"].raw == "demo"
        assert parsed["name"].style is None
        assert parsed["description"].style == ">-"
        assert parsed["description"].raw == "Line one\nline two."

    def test_keeps_the_block_scalar_indicator_apart(self):
        parsed = nice_check.parse_frontmatter("---\ndescription: >\n  Text.\n---\n")

        assert parsed["description"].style == ">"

    def test_records_line_numbers(self):
        parsed = nice_check.parse_frontmatter('---\nname: demo\nversion: "1.0.0"\n---\n')

        assert parsed["name"].line == 2
        assert parsed["version"].line == 3

    def test_reads_a_list_value_without_confusing_it_for_a_scalar(self):
        parsed = nice_check.parse_frontmatter("---\nallowed-tools:\n  - Read\n  - Write\nname: demo\n---\n")

        assert parsed["allowed-tools"].raw == "- Read\n- Write"
        assert parsed["name"].raw == "demo"

    def test_rejects_a_file_without_frontmatter(self):
        try:
            nice_check.parse_frontmatter("# Title\n")
        except nice_check.FrontmatterError as exc:
            assert "does not open" in str(exc)
        else:
            raise AssertionError("expected FrontmatterError")

    def test_rejects_an_unterminated_block(self):
        try:
            nice_check.parse_frontmatter("---\nname: demo\n")
        except nice_check.FrontmatterError as exc:
            assert "never closed" in str(exc)
        else:
            raise AssertionError("expected FrontmatterError")


