# -- E. dead relative links --------------------------------------------------


class TestCheckMarkdownLinks:
    def link_repo(self, tmp_path, rel: str, text: str) -> nice_check.Repo:
        tracked = [write(tmp_path, rel, text)]
        tracked.append(write(tmp_path, "plugins/core/README.md", "# core\n"))
        return make_repo(tmp_path, tracked)

    def test_reports_a_dotted_link_leaving_the_repo_into_nothing(self, tmp_path):
        repo = self.link_repo(tmp_path, "plugins/lab/skills/demo/SKILL.md", "See [rules](../../rules/clean-code.md).\n")

        findings = nice_check.check_markdown_links(repo)

        assert findings[0].severity == "error"
        assert findings[0].line == 1

    def test_accepts_a_dotted_link_that_resolves(self, tmp_path):
        repo = self.link_repo(tmp_path, "plugins/lab/README.md", "See [core](../core/README.md).\n")

        assert nice_check.check_markdown_links(repo) == []

    def test_ignores_illustrative_targets(self, tmp_path):
        body = "[text](url) [file.ts:42](file.ts#L42) [path/to/file.ext:42](path/to/file.ext#L42)\n"
        repo = self.link_repo(tmp_path, "plugins/core/rules/markdown-style.md", body)

        assert nice_check.check_markdown_links(repo) == []

    def test_checks_a_bare_target_starting_at_a_repo_root_entry(self, tmp_path):
        repo = self.link_repo(tmp_path, "README.md", "[core](plugins/core/README.md) [gone](plugins/gone/README.md)\n")

        findings = nice_check.check_markdown_links(repo)

        assert len(findings) == 1
        assert "plugins/gone/README.md" in findings[0].message

    def test_ignores_the_fragment_of_an_existing_target(self, tmp_path):
        repo = self.link_repo(tmp_path, "README.md", "[core](plugins/core/README.md#L4)\n")

        assert nice_check.check_markdown_links(repo) == []

    def test_ignores_external_links(self, tmp_path):
        repo = self.link_repo(tmp_path, "README.md", "[docs](https://example.invalid/x) [mail](mailto:a@b.c)\n")

        assert nice_check.check_markdown_links(repo) == []


# -- F. hook configuration ---------------------------------------------------


class TestCheckHookConfigs:
    def write_hooks(self, tmp_path, events: dict) -> nice_check.Repo:
        write(tmp_path, "plugins/core/hooks/hooks.json", json.dumps({"hooks": events}))
        return make_repo(tmp_path)

    def test_reports_a_matcher_used_twice_in_one_event(self, tmp_path):
        write(tmp_path, "plugins/core/hooks/one.sh", "")
        write(tmp_path, "plugins/core/hooks/two.sh", "")
        blocks = [
            {"matcher": "Edit|Write", "hooks": [{"command": "bash ${CLAUDE_PLUGIN_ROOT}/hooks/one.sh"}]},
            {"matcher": "Edit|Write", "hooks": [{"command": "bash ${CLAUDE_PLUGIN_ROOT}/hooks/two.sh"}]},
        ]
        repo = self.write_hooks(tmp_path, {"PostToolUse": blocks})

        findings = nice_check.check_hook_configs(repo)

        assert len(findings) == 1
        assert "is used twice" in findings[0].message

    def test_accepts_matchers_that_only_overlap(self, tmp_path):
        write(tmp_path, "plugins/core/hooks/one.sh", "")
        blocks = [
            {"matcher": "Edit|Write", "hooks": [{"command": "bash ${CLAUDE_PLUGIN_ROOT}/hooks/one.sh"}]},
            {"matcher": "Edit|Write|Bash", "hooks": [{"command": "bash ${CLAUDE_PLUGIN_ROOT}/hooks/one.sh"}]},
        ]
        repo = self.write_hooks(tmp_path, {"PostToolUse": blocks})

        assert nice_check.check_hook_configs(repo) == []

    def test_reports_a_script_that_is_not_there(self, tmp_path):
        blocks = [{"matcher": "Bash", "hooks": [{"command": "python3 ${CLAUDE_PLUGIN_ROOT}/hooks/gone.py"}]}]
        repo = self.write_hooks(tmp_path, {"PreToolUse": blocks})

        findings = nice_check.check_hook_configs(repo)

        assert "gone.py does not exist" in findings[0].message

    def test_expands_the_project_directory_variable(self, tmp_path):
        write(tmp_path, "scripts/sync.py", "")
        blocks = [{"hooks": [{"command": 'python3 "${CLAUDE_PROJECT_DIR}/scripts/sync.py"'}]}]
        repo = self.write_hooks(tmp_path, {"UserPromptSubmit": blocks})

        assert nice_check.check_hook_configs(repo) == []

    def test_reports_invalid_json_instead_of_raising(self, tmp_path):
        write(tmp_path, "plugins/core/hooks/hooks.json", "{oops")

        findings = nice_check.check_hook_configs(make_repo(tmp_path))

        assert findings[0].severity == "error"
        assert "invalid JSON" in findings[0].message


