class TestCheckTextHygiene:
    def test_reports_crlf_line_endings(self, tmp_path):
        tracked = [write(tmp_path, "a.sh", "echo hi\n")]

        findings = nice_check.check_text_hygiene(make_repo(tmp_path, tracked, {"a.sh": "crlf"}))

        assert "CRLF" in findings[0].message

    def test_reports_trailing_whitespace_outside_markdown(self, tmp_path):
        tracked = [write(tmp_path, "a.sh", "echo hi  \n")]

        findings = nice_check.check_text_hygiene(make_repo(tmp_path, tracked))

        assert messages(findings) == ["a.sh:1: trailing whitespace"]

    def test_leaves_trailing_whitespace_in_markdown_alone(self, tmp_path):
        tracked = [write(tmp_path, "a.md", "line  \n")]

        assert nice_check.check_text_hygiene(make_repo(tmp_path, tracked)) == []

    def test_reports_a_long_line_in_a_shell_script(self, tmp_path):
        tracked = [write(tmp_path, "a.ps1", "#" * 121 + "\n")]

        findings = nice_check.check_text_hygiene(make_repo(tmp_path, tracked))

        assert "121 characters" in findings[0].message

    def test_leaves_long_python_lines_to_ruff(self, tmp_path):
        tracked = [write(tmp_path, "a.py", "#" * 200 + "\n")]

        assert nice_check.check_text_hygiene(make_repo(tmp_path, tracked)) == []

    def test_reports_a_missing_final_newline(self, tmp_path):
        tracked = [write(tmp_path, "a.sh", "echo hi")]

        findings = nice_check.check_text_hygiene(make_repo(tmp_path, tracked))

        assert "does not end with a newline" in findings[0].message

    def test_reports_accented_letters(self, tmp_path):
        # The accents are \u escapes so this test file itself stays ASCII - nice-check scans its own repo.
        tracked = [write(tmp_path, "a.md", "kontrola nen\u00ed hotov\u00e1\n")]

        findings = nice_check.check_text_hygiene(make_repo(tmp_path, tracked))

        assert "non-ASCII letters" in findings[0].message

    def test_accepts_dashes_arrows_and_math_signs(self, tmp_path):
        tracked = [write(tmp_path, "a.md", "a — b → c ≠ d\n")]

        assert nice_check.check_text_hygiene(make_repo(tmp_path, tracked)) == []

    def test_reports_a_generator_placeholder(self, tmp_path):
        # Split so the literal phrase never appears in this file either - the check
        # matches "Add your" and "description here" across any run of whitespace.
        tracked = [write(tmp_path, "a.md", "Add your " + "description here\n")]

        findings = nice_check.check_text_hygiene(make_repo(tmp_path, tracked))

        assert "generator placeholder" in findings[0].message

    def test_reports_a_file_that_is_not_utf8(self, tmp_path):
        (tmp_path / "a.md").write_bytes(b"\xff\xfe binary\n")

        findings = nice_check.check_text_hygiene(make_repo(tmp_path, ["a.md"]))

        assert findings[0].severity == "error"
        assert "cannot read the file" in findings[0].message


# -- J. stray tracked files --------------------------------------------------


class TestCheckStrayTrackedFiles:
    def test_reports_a_tracked_plan(self, tmp_path):
        findings = nice_check.check_stray_tracked_files(make_repo(tmp_path, [".claude/plans/x.md", "README.md"]))

        assert messages(findings) == [
            ".claude/plans/x.md:None: plans are local scratch; .claude/plans/ must stay untracked"
        ]

    def test_accepts_a_repo_without_tracked_plans(self, tmp_path):
        assert nice_check.check_stray_tracked_files(make_repo(tmp_path, ["README.md"])) == []


# -- whole run ---------------------------------------------------------------


class TestRunChecks:
    def test_broken_input_is_a_finding_and_the_other_checks_still_run(self, tmp_path):
        write(tmp_path, ".claude-plugin/marketplace.json", "{broken\n")
        write(tmp_path, "plugins/core/skills/demo/SKILL.md", "# no frontmatter\n")
        tracked = [".claude-plugin/marketplace.json", write(tmp_path, "a.sh", "echo hi  \n")]

        findings = nice_check.run_checks(make_repo(tmp_path, tracked))

        assert [(finding.check, finding.severity) for finding in findings] == [
            ("A", "error"),
            ("B", "error"),
            ("D", "warning"),
            ("I", "warning"),
        ]
